"""Print fingerprints of the labelled domains generated by the original skeleton enumerator."""
from hashlib import sha256
from pathlib import Path
import sys
outdir=Path(sys.argv[1]) if len(sys.argv)>1 else None
if outdir is not None: outdir.mkdir(parents=True, exist_ok=True)
from skeleton import sectors, choices
from high_normals import actions
orbitdir=Path(sys.argv[2]) if len(sys.argv)>2 else None
if orbitdir is not None:orbitdir.mkdir(parents=True,exist_ok=True)

for _, _, key, factors, columns, live in sectors():
    words, choices_iterator = choices(factors, columns, live)
    codes = [sum(k*3**i for i,k in enumerate(row[0])) for row in words]
    subsets = [subset for subset,_,_ in choices_iterator]
    encode=lambda s:tuple(sorted(codes[j] for j in s))
    tuples = sorted(map(encode,subsets))
    if orbitdir is not None:
        perms=actions(factors,columns,words)
        unseen=set(subsets); assignments=[]
        while unseen:
            seed=unseen.pop(); queue=[seed]
            for s in queue:
                for g in perms:
                    t=tuple(sorted(g[j] for j in s))
                    if t in unseen:unseen.remove(t);queue.append(t)
            orbit=list(map(encode,queue)); representative=min(orbit)
            assignments.extend((v,representative) for v in orbit)
        dest=orbitdir/f"{factors.count('A1')}_{factors.count('A2')}_{key}.txt"
        dest.write_text(''.join(' '.join(map(str,k))+'|'+' '.join(map(str,v))+'\n' for k,v in sorted(assignments)))
    serialized = ''.join(' '.join(map(str,r))+'\n' for r in tuples)
    if outdir is not None:
        (outdir/f"{factors.count('A1')}_{factors.count('A2')}_{key}.txt").write_text(serialized, encoding='ascii')
    print(factors.count('A1'),factors.count('A2'),key,len(tuples),sha256(serialized.encode()).hexdigest(),flush=True)
